import {KEY,seed,slots,cities,uid,match,accept,confirm,stage,occupied,notify,nextMeeting} from './model.js';
const $=s=>document.querySelector(s),main=$('#main');let state;try{state=JSON.parse(localStorage.getItem(KEY));if(state?.version!==1)state=seed();}catch{state=seed();}let role='participant',hostId='calgary-men',staffTab='approvals',formProfile=null,storageWarning=false;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=(arr,value)=>arr.map(v=>`<option ${v===value?'selected':''}>${e(v)}</option>`).join('');
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageWarning=true;toast('Browser storage is unavailable. Changes will last for this visit only.');}};
const toast=s=>{$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);};
const go=path=>{location.hash=path;};
const bandForUser=()=>state.user&&state.bands.find(b=>b.members.some(m=>m.email===state.user.email));
const activeRequest=()=>state.user&&state.requests.find(r=>r.email===state.user.email&&['review','offered','waiting'].includes(r.status));
function page(title,body,sub=''){return `<section class="page narrow"><a class="back" href="#home">← Back to home</a><h1>${title}</h1>${sub?`<p class="lead">${sub}</p>`:''}${body}</section>`;}
function openDialog(html){$('#dialog-body').innerHTML=html;$('#dialog').showModal();}
function localMeeting(b){try{return new Intl.DateTimeFormat(undefined,{timeZone:state.user?.zone||Intl.DateTimeFormat().resolvedOptions().timeZone,dateStyle:'full',timeStyle:'short'}).format(nextMeeting(b));}catch{return b.slot;}}
function event(to,subject,body){notify(state,to,subject,body);}
const art=`<div class="art"><img src="${new URL('./men-bible.webp',import.meta.url).href}" alt="Two men reading and discussing Bibles together." width="1000" height="1000" fetchpriority="high" decoding="async"><a class="photo-credit" href="https://www.pexels.com/photo/two-people-reading-bible-while-sitting-on-a-sofa-6860819/" target="_blank" rel="noopener">Photo: Tima Miroshnichenko / Pexels</a></div>`;
function home(){main.innerHTML=`<section class="hero"><div><div class="eyebrow">Life is better together</div><h1>Find your people.<br>Share your life.<br><em>Grow with Jesus.</em></h1><p class="lead">You don't have to follow Jesus on your own. A Discipleship Band is a few people making room for honest conversation, Scripture and prayer.</p><div class="actions"><a class="primary" href="#join">Join a Band <span aria-hidden="true">↗</span></a><a class="secondary" href="#start">Start a Band <span aria-hidden="true">+</span></a></div><p class="tiny">Meet in person or online. Begin with a six-month commitment.</p></div>${art}</section><section class="intro-strip" aria-label="How Bands work"><div><span class="num">01</span><div><b>Find a few people</b><p>3–5 men or women. A time that fits.</p></div></div><div><span class="num">02</span><div><b>Make room each week</b><p>Show up. Listen. Share honestly.</p></div></div><div><span class="num">03</span><div><b>Follow Jesus together</b><p>Scripture, prayer and everyday life.</p></div></div></section><section class="home-bottom"><div><h2>You don't need to have it all figured out.</h2><p>Just a willingness to show up and grow. We'll help you take the next step, whether you're starting fresh or bringing a few friends.</p></div><a class="text-link" href="#guide">What happens in a Band? ↗</a></section>`;}
function auth(intent){main.innerHTML=page("Let's get you connected.",`<div class="card"><span class="tag">DEMO SIGN-IN</span><p>In the connected app, we'll email you a secure sign-in link. Here, you can try the same flow with a made-up email.</p><form id="auth-form" data-intent="${e(intent)}"><label for="email">Your email</label><input id="email" name="email" type="email" required autocomplete="email" placeholder="you@example.test"><button class="primary mt">Preview sign-in email ↗</button></form></div>`);}
const field=(label,name,html,hint='')=>`<div><label for="${name}">${label}</label>${html}${hint?`<p class="hint">${hint}</p>`:''}</div>`;
function profileFields(u={},isHost=false){const zones=[...new Set([Intl.DateTimeFormat().resolvedOptions().timeZone,'America/Edmonton','America/Regina','America/Vancouver','America/Toronto','America/Halifax','Europe/London','Asia/Tehran','America/Sao_Paulo','Australia/Sydney'])];return `<div class="form-grid">${field('Your name','name',`<input id="name" name="name" maxlength="80" required value="${e(u.name)}" autocomplete="name">`)}${isHost?field('Band name','bandname','<input id="bandname" name="bandname" maxlength="80" required placeholder="A simple name for your Band">'):''}${field('Band for','gender',`<select id="gender" name="gender">${options(['Men','Women'],u.gender)}</select>`)}${field('Meeting language','language',`<select id="language" name="language">${options(['English','Farsi','Portuguese','Spanish'],u.language)}</select>`)}${field('Meet','format',`<select id="format" name="format">${options(isHost?['In person','Online']:['In person','Online','Either'],u.format)}</select>`)}${field('City or neighbourhood','city',`<input id="city" name="city" list="cities" required value="${e(u.city||'Calgary')}" maxlength="100"><datalist id="cities">${Object.keys(cities).map(c=>`<option value="${c.replaceAll('_',' ')}">`).join('')}</datalist>`,'Choose a suggested city, or enter your city and use GPS below. Online Bands can use any city.')}${field('Your time zone','zone',`<select id="zone" name="zone">${options(zones,u.zone||Intl.DateTimeFormat().resolvedOptions().timeZone)}</select>`)}${!isHost?field('How far can you travel? (km)','radius',`<input id="radius" name="radius" type="number" min="1" max="2000" step="1" value="${u.radius||20}" required>`,'Used for in-person meetings only. Distance is straight-line, not driving distance.'):''}</div><section class="mt" aria-labelledby="gps-label"><h3 id="gps-label">Choose your location</h3><p class="hint">${isHost?'Use GPS while you’re at the meeting venue, or choose its city above. Your device location is used only when you press the button.':'Use GPS to set your approximate area for distance matching, or choose a suggested city above.'}</p><input id="lat" name="lat" type="hidden" value="${u.lat??''}"><input id="lon" name="lon" type="hidden" value="${u.lon??''}"><button type="button" class="secondary" id="gps" aria-describedby="gps-status">Use my location</button><p class="hint" id="gps-status" role="status">${Number.isFinite(u.lat)&&Number.isFinite(u.lon)?'Your saved approximate location is selected. You can update it with GPS.':'Your browser will ask for location permission. We save only an approximate area.'}</p></section>`;}
function join(){if(!state.user)return auth('join');if(bandForUser()||activeRequest())return go('my');const u=formProfile||state.user;main.innerHTML=page('Make room for community.',`<div class="card"><form id="join-form">${profileFields(u)}<fieldset><legend>When could you meet each week?</legend><p class="hint">Choose all that fit. Times are in your selected time zone. These are sample weekly slots for the demo.</p>${slots.map(s=>`<label class="check"><input type="checkbox" name="availability" value="${s}" ${(u.slots||['Saturday 10:00']).includes(s)?'checked':''}>${s}</label>`).join('')}</fieldset><label class="check"><input type="checkbox" name="agreement" required>I’m ready to commit to meeting regularly for six months and respect the <a href="#agreement" class="text-link">Band Agreement</a>.</label><p class="hint">We'll privately ask one eligible host at a time. You'll hear when a host has accepted, then decide whether to join.</p><p id="form-error" class="error" role="alert"></p><button class="primary">Find a match ↗</button></form></div>`,'Tell us a little about what works for you.');}
function start(){if(!state.user)return auth('start');if(bandForUser())return go('my');main.innerHTML=page('Start something meaningful.',`<div class="card"><form id="start-form">${profileFields(state.user,true)}<div class="form-grid mt">${field('Weekly meeting','slot',`<select id="slot" name="slot">${options(slots,'Saturday 10:00')}</select>`)}</div><p class="hint">Weekly meeting time is in the selected time zone. Start meeting once three people have confirmed.</p><label for="location" class="mt">Private meeting address or area</label><input id="location" name="location" maxlength="180" placeholder="For in-person Bands. Only confirmed members see this."><label for="link" class="mt">Online meeting link</label><input id="link" name="link" type="url" placeholder="https://…"><label class="check mt"><input type="checkbox" name="open" checked>Open my Band to matching after staff approval.</label><label class="check"><input type="checkbox" required>I’ll welcome people, review requests, keep meeting details accurate and follow the <a class="text-link" href="#agreement">Band Agreement</a>.</label><p class="notice">FAC staff will review your Band before anyone can join or be matched. Invitations also wait for approval.</p><p id="form-error" class="error" role="alert"></p><button class="primary">Send for staff approval ↗</button></form></div>`,'Bring a few people together. You don’t need to be an expert.');}
function guide(agreement=false){main.innerHTML=page(agreement?'Our Band Agreement.':'A little space for honest life.',agreement?`<div class="card"><p>These draft expectations are here to help you test the demo. FAC will approve final wording before launch.</p><ul class="guide-list"><li>Show up regularly and commit to the first six months.</li><li>Listen with care. Make room for everyone to share.</li><li>Keep Scripture, prayer and following Jesus at the centre.</li><li>Respect confidentiality. Safety concerns must still be shared with appropriate support.</li><li>Don’t record meetings or store sensitive disclosures in the app.</li><li>Bands offer discipleship and encouragement. They don’t replace counselling, pastoral care or emergency support.</li></ul><button class="text-link" data-help="concern">Contact FAC about a concern</button></div>`:`<div class="card soft"><span class="tag">FIRST MEETING GUIDE</span><h2 class="mt">Begin with getting to know each other.</h2><p>Share why you’re here, agree on a weekly time and place, and talk through the <a class="text-link" href="#agreement">Band Agreement</a>. Pray for one another and choose when you’ll meet again.</p></div><div class="card"><h2>Let these questions open the conversation.</h2><ol class="guide-list"><li>How is your soul?</li><li>What are your successes and struggles?</li><li>How is God’s Word and Spirit speaking to you?</li></ol><h3>As trust grows</h3><p>There’s no forced timeline. When your Band is ready, you may ask:</p><ul class="guide-list"><li>Is there any sin you need to confess?</li><li>Is there anything you’re holding back or keeping secret?</li></ul><p class="hint">These are questions for conversation. The app doesn’t collect or store your answers.</p><button class="secondary" id="print-guide">Print or save this guide ↗</button></div>`);}
function my(){if(!state.user)return auth('my');const b=bandForUser(),r=activeRequest();if(b){main.innerHTML=page(`Your Band: ${e(b.name)}`,`<div class="status-heading"><span class="tag">${stage(b)} · ${b.members.length}/5 people</span><a class="text-link" href="#inbox">Updates & demo emails</a></div>${!b.approved?'<p class="notice">Your Band is awaiting FAC staff approval. Private details below are visible to you as the host in this demo.</p>':''}<div class="card soft"><h2>${b.members.length>=3?'Your next meeting':'Getting ready to meet'}</h2><div class="schedule">${e(localMeeting(b))}</div><p class="hint">Displayed in ${e(state.user.zone||Intl.DateTimeFormat().resolvedOptions().timeZone)} · Host schedule: ${e(b.slot)} (${e(b.zone)})</p>${b.members.length<3?'<p>Begin meeting once three people have confirmed. This weekly time is proposed while your Band forms.</p>':''}${b.format==='Online'?`<a class="primary" href="${safeUrl(b.link)}" target="_blank" rel="noopener">Open meeting link ↗</a><p class="hint">Demo links open the provider’s website.</p>`:`<p><b>Meeting location</b><br>${e(b.location)}</p>`}</div><div class="card"><h2>The people in your Band</h2><ul class="members">${b.members.map(m=>`<li><span class="avatar">${e(m.name.slice(0,1))}</span><span>${e(m.name)} ${m.email===b.email?'<span class="pill">Host</span>':''}</span></li>`).join('')}</ul></div><div class="actions"><a class="secondary" href="#guide">First Meeting Guide ↗</a>${b.email===state.user.email?`<button class="secondary" data-host="${e(b.id)}">Host controls ↗</button>`:''}<button class="text-link" data-help="concern">Report a concern</button></div><div class="card"><h2>At six months, reflect together.</h2><p>You can renew, multiply, reconfigure, conclude intentionally, or ask FAC for help.</p><button class="secondary" data-journey="${e(b.id)}">Explore next steps ↗</button></div>${b.email!==state.user.email?`<button class="text-link" data-leave="${e(b.id)}">Leave this Band</button>`:'<p class="hint">If you need to step down as host, contact FAC to arrange a handover.</p>'}`);return;}let content;if(r?.status==='review')content=`<span class="status-dot">◷</span><h2>Awaiting Host Review</h2><p>We've privately sent your request to one eligible Band. Once a host accepts, you'll receive an update here and a simulated email.</p><p class="hint">For testing, open Demo controls and choose “Host” to review your request.</p><button class="secondary" data-withdraw="${r.id}">Withdraw request</button>`;else if(r?.status==='offered'){const b=state.bands.find(b=>b.id===r.band);content=`<span class="tag">Accepted—Your Confirmation Needed</span><h2>There's a place for you in ${e(b.name)}.</h2><p>${e(b.host)} has welcomed your request. Would you like to join?</p><p>${e(b.format)} · ${e(b.city)} · ${e(b.language)}<br>${e(localMeeting(b))}</p><p class="hint">Exact location and meeting links unlock after you confirm.</p><div class="actions"><button class="primary" data-confirm="${r.id}">Confirm my place ↗</button><button class="secondary" data-decline="${r.id}">Decline & try another</button></div>`;}else if(r?.status==='waiting')content=`<span class="tag">Waiting for a Match</span><h2>We'll keep a place on the waiting list.</h2><p>You’ve agreed to be contacted when a suitable Band becomes available. You can check again or withdraw at any time.</p><div class="actions"><button class="primary" id="retry">Check for a match ↗</button><button class="secondary" data-withdraw="${r.id}">Withdraw</button></div>`;else content=`<h2>Ready to find your people?</h2><div class="actions"><a class="primary" href="#join">Join a Band ↗</a><a class="secondary" href="#start">Start a Band +</a></div>`;main.innerHTML=page('Your next step.',`<div class="card">${content}</div><a class="text-link" href="#inbox">Updates & demo emails ↗</a><p><button class="text-link" data-help="support">Can't find a Band that fits? Let us help.</button></p>`);}
function noMatch(){main.innerHTML=page('Let’s keep the door open.',`<div class="card"><h2>We don’t see a Band that fits right now.</h2><p>Would you like us to contact you when one becomes available?</p><p class="hint">We’ll retain your matching preferences only if you join the waiting list. You can withdraw at any time.</p><div class="actions"><button class="primary" id="waitlist">Yes, join the waiting list ↗</button><a class="secondary" href="#join">Change my preferences</a></div><button class="text-link" data-help="support">Can’t find a Band that fits? Let us help.</button></div>`);}
function host(){role='host';const b=state.bands.find(b=>b.id===hostId)||state.bands[0];hostId=b.id;const requests=state.requests.filter(r=>r.band===b.id&&r.status==='review');main.innerHTML=`<section class="page"><a class="back" href="#home">← Home</a><div class="status-heading"><h1>Welcome, ${e(b.host)}.</h1><span class="tag">DEMO HOST VIEW</span></div><p>${e(b.name)} · ${stage(b)} · ${b.members.length} confirmed members · ${occupied(state,b)-b.members.length} reserved places</p><p class="hint">This demo lets you switch between sample hosts. Real host access will require a verified account.</p>${!b.approved?'<p class="notice">Awaiting FAC staff approval. Recruitment and invitations are unavailable until approved.</p>':''}<div class="card"><h2>Review requests ${requests.length?`(${requests.length})`:''}</h2>${requests.length?requests.map(r=>`<div class="split"><div><b>${e(r.name)}</b><p class="hint">${e(r.profile.language)} · ${e(r.profile.format)} · ${e(r.profile.city)}</p></div><div class="actions"><button class="primary" data-accept="${r.id}" ${!b.approved?'disabled':''}>Accept</button><button class="secondary" data-reject="${r.id}">Decline</button></div></div>`).join(''):'<p>No requests awaiting your review.</p>'}<p class="hint">An accepted person still needs to confirm. An offer reserves one of your five places.</p></div><div class="grid"><div class="card"><h2>Members</h2><ul class="members">${b.members.map(m=>`<li><span class="avatar">${e(m.name.slice(0,1))}</span>${e(m.name)}${m.email===b.email?' · Host':''}</li>`).join('')}</ul><p class="hint">${state.requests.filter(r=>r.band===b.id&&r.status==='offered').length} people awaiting confirmation.</p></div><div class="card"><h2>Invite a friend</h2><form id="invite-form"><label for="friend">Friend's email</label><input id="friend" name="friend" type="email" required placeholder="friend@example.test" ${!b.approved?'disabled':''}><button class="secondary mt" ${!b.approved?'disabled':''}>Create demo invitation ↗</button></form><p class="hint">Invited friends confirm their details, Band fit and participation before joining. Invitations don't reserve space.</p></div></div><div class="card"><h2>Update meeting details</h2><form id="meeting-form"><div class="form-grid">${field('Weekly time','slot',`<select id="slot" name="slot">${options(slots,b.slot)}</select>`)}${field('Time zone','zone',`<select id="zone" name="zone">${options([...new Set([b.zone,'America/Edmonton','Europe/London','Asia/Tehran','America/Toronto'])],b.zone)}</select>`)}${field(b.format==='Online'?'Meeting link':'Private meeting location','location',`<input id="location" name="location" ${b.format==='Online'?'type="url"':''} required value="${e(b.format==='Online'?b.link:b.location)}" maxlength="200">`)}</div><p class="hint">City and coordinates set the matching location. Changes to that location need a new staff review.</p><label class="check mt"><input type="checkbox" name="open" ${b.open?'checked':''}>Open to matching while space is available</label><button class="primary">Save meeting details</button></form></div></section>`;}
function staff(){role='staff';const pending=state.bands.filter(b=>!b.approved);const tabs=[['approvals','Approvals'],['bands','Bands'],['requests','Introductions'],['waiting','Waiting list'],['help','Help & concerns']];main.innerHTML=`<section class="page"><a class="back" href="#home">← Home</a><div class="status-heading"><h1>Make connection possible.</h1><span class="tag">DEMO STAFF VIEW</span></div><div class="metrics"><div><strong>${state.bands.filter(b=>b.approved).length}</strong><span>Approved Bands</span></div><div><strong>${state.bands.reduce((n,b)=>n+b.members.length,0)}</strong><span>Confirmed members</span></div><div><strong>${state.bands.filter(b=>b.members.length>=3).length}</strong><span>Meeting-size Bands</span></div></div><div class="tabs">${tabs.map(([key,label])=>`<button data-tab="${key}" aria-current="${key===staffTab}">${label}${key==='approvals'?` (${pending.length})`:''}</button>`).join('')}</div>${staffTab==='approvals'?(pending.map(b=>`<div class="card split"><div><h2>${e(b.name)}</h2><p>${e(b.host)} · ${e(b.email)}<br>${e(b.gender)} · ${e(b.language)} · ${e(b.city)} · ${e(b.format)}<br>${e(b.slot)} (${e(b.zone)})</p></div><div><button class="primary" data-approve="${b.id}">Approve Band ↗</button><button class="secondary" data-return="${b.id}">Request changes</button></div></div>`).join('')||'<div class="card">No Bands awaiting approval.</div>'):staffTab==='bands'?state.bands.map(b=>`<div class="card split"><div><b>${e(b.name)}</b><p>${stage(b)} · ${b.members.length}/5 people · ${e(b.city)}</p></div><button class="secondary" data-host="${b.id}">Preview host view</button></div>`).join(''):staffTab==='requests'?state.requests.filter(r=>['review','offered'].includes(r.status)).map(r=>`<div class="card"><b>${e(r.name)}</b><p>${e(state.bands.find(b=>b.id===r.band)?.name)} · ${r.status==='review'?'Awaiting Host Review':'Accepted—Your Confirmation Needed'}</p></div>`).join('')||'<div class="card">No pending introductions.</div>':staffTab==='waiting'?state.requests.filter(r=>r.status==='waiting').map(r=>`<div class="card"><b>${e(r.name)}</b><p>${e(r.email)} · ${e(r.profile.city)} · ${e(r.profile.language)}</p><p class="hint">Permission to contact given.</p><button class="secondary" data-rematch="${r.id}">Check for eligible Band</button></div>`).join('')||'<div class="card">No waiting-list requests.</div>':state.help.map(h=>`<div class="card"><span class="tag">${h.type==='concern'?'Safety concern':'Connection help'}</span><h2>${e(h.email)}</h2><p>${e(h.message)}</p><p class="hint">${h.resolved?'Marked reviewed':'Awaiting review'}</p>${!h.resolved?`<button class="secondary" data-resolve="${h.id}">Mark reviewed</button>`:''}</div>`).join('')||'<div class="card">No help requests.</div>'}</section>`;}
function inbox(){const events=role==='staff'?state.events:state.events.filter(x=>x.to===(role==='host'?state.bands.find(b=>b.id===hostId)?.email:state.user?.email));main.innerHTML=page('Your updates.',`<p class="notice">These are simulated emails and in-app updates. Nothing has been sent.</p>${events.map(x=>`<article class="card"><span class="tag">DEMO EMAIL</span><h2 class="mt">${e(x.subject)}</h2><p class="hint">To: ${e(x.to)} · ${new Date(x.date).toLocaleString()}</p><p>${e(x.body)}</p></article>`).join('')||'<div class="card">No updates yet.</div>'}`);}
function demoPanel(){$('#demo-panel').innerHTML=`<b>Try every part of the journey</b><p class="hint">Switch roles to act on the same browser’s sample data. This is a testing tool, not real sign-in.</p><button data-role="participant">Participant</button><button data-role="host">Host</button><button data-role="staff">FAC staff</button><label for="host-select">Sample host</label><select id="host-select">${state.bands.map(b=>`<option value="${b.id}" ${b.id===hostId?'selected':''}>${e(b.host)} · ${e(b.name)}</option>`).join('')}</select><button data-demo="inbox">View simulated emails</button><button data-demo="signout">Sign out participant</button><button data-demo="reset">Reset demo data</button>`;}
function render(){const path=location.hash.slice(1)||'home';$('#account').textContent=state.user?'My Band':'Sign in';({home,join,start,my,guide,agreement:()=>guide(true),host,staff,inbox,nomatch:noMatch}[path]||home)();demoPanel();window.scrollTo(0,0);}
function safeUrl(v){try{const u=new URL(v);return u.protocol==='https:'?e(u.href):'#';}catch{return '#';}}
function readProfile(f){const d=new FormData(f),city=d.get('city').trim();const known=cities[city.replaceAll(' ','_')];const lat=d.get('lat')!==''?Number(d.get('lat')):known?.[0],lon=d.get('lon')!==''?Number(d.get('lon')):known?.[1];const format=d.get('format');if(format!=='Online'&&(!Number.isFinite(lat)||!Number.isFinite(lon)))throw Error('Use my location or choose a suggested city for in-person distance matching. You don’t need to enter coordinates.');return {...state.user,name:d.get('name').trim(),gender:d.get('gender'),language:d.get('language'),format,city,lat,lon,radius:Number(d.get('radius')||20),zone:d.get('zone'),slots:d.getAll('availability')};}
function tryMatch(u){const r=match(state,u);if(r){const b=state.bands.find(b=>b.id===r.band);event(b.email,'A new Band request',`${u.name} would like to connect. Open your host controls to review.`);save();go('my');render();}else{save();go('nomatch');render();}}
function requestHelp(type){openDialog(`<h2>${type==='concern'?'Share a concern with FAC.':'Let’s help you get connected.'}</h2><p class="notice">Demo only. FAC will not receive this form. Use your usual church contact for actual help.</p><form id="help-form" data-type="${type}"><label for="help-email">Your email</label><input id="help-email" name="email" type="email" required value="${e(state.user?.email||'')}"><label for="message" class="mt">${type==='concern'?'Brief concern category or request for a private conversation':'How can we help?'}</label><textarea id="message" name="message" required maxlength="500" rows="3"></textarea><p class="hint">Please don’t enter confessions, detailed personal struggles or sensitive disclosures. For immediate danger, contact emergency services.</p><button class="primary">Save demo request</button></form>`);}
function inviteDialog(i){const b=state.bands.find(b=>b.id===i.band);if(!state.user||state.user.email!==i.email){toast('Sign in as the invited email using Demo controls → Sign out participant.');return;}openDialog(`<h2>Join ${e(b.name)}?</h2><p>${e(b.gender)} · ${e(b.language)} · ${e(b.format)} · ${e(b.city)}<br>${e(localMeeting(b))}</p><p class="hint">Confirm that this Band’s gender, language and meeting arrangements fit you. Meeting details unlock after you join.</p><label class="check"><input type="checkbox" id="invite-agree">I meet these requirements and agree to the six-month Band commitment.</label><button class="primary" data-invite-confirm="${i.id}">Confirm participation</button>`);}
window.addEventListener('hashchange',render);
$('#demo-toggle').onclick=()=>{$('#demo-panel').hidden=!$('#demo-panel').hidden;$('#demo-toggle').setAttribute('aria-expanded',String(!$('#demo-panel').hidden));};
$('#account').onclick=()=>{role='participant';go('my');render();};
document.addEventListener('change',ev=>{if(ev.target.id==='host-select'){hostId=ev.target.value;if(role==='host'){go('host');render();}}if(ev.target.id==='city'){const c=Object.entries(cities).find(([name])=>name.replaceAll('_',' ').toLowerCase()===ev.target.value.trim().toLowerCase())?.[1];$('#lat').value=c?.[0]??'';$('#lon').value=c?.[1]??'';$('#gps-status').textContent=c?'City area selected for distance matching. Use GPS for your current area instead.':'City updated. Use GPS for in-person distance matching. Online Bands don’t require GPS.';}});
document.addEventListener('submit',ev=>{const f=ev.target;if(f.method==='dialog')return;ev.preventDefault();const d=new FormData(f);try{if(f.id==='auth-form'){const email=d.get('email').trim().toLowerCase(),intent=f.dataset.intent;openDialog(`<span class="tag">SIMULATED MAGIC LINK</span><h2>Your sign-in email is ready.</h2><p>To: ${e(email)}</p><p>In the connected app, this button would arrive in your inbox.</p><button class="primary" id="magic" data-email="${e(email)}" data-intent="${e(intent)}">Use demo sign-in link ↗</button>`);}else if(f.id==='join-form'){const u=readProfile(f);if(!u.name||!u.slots.length)throw Error('Enter your name and select at least one meeting time.');state.user=u;formProfile=u;tryMatch(u);}else if(f.id==='start-form'){const u=readProfile(f);if(!u.name)throw Error('Please enter your name.');if(u.format==='In person'&&!d.get('location').trim())throw Error('Add a private meeting location for your in-person Band.');if(u.format==='Online'&&!d.get('link'))throw Error('Add an online meeting link.');if(d.get('link')&&!String(d.get('link')).startsWith('https://'))throw Error('Use a secure https:// meeting link.');const b={id:uid(),name:d.get('bandname').trim(),host:u.name,email:u.email,gender:u.gender,language:u.language,format:u.format,city:u.city,lat:u.lat,lon:u.lon,slot:d.get('slot'),zone:u.zone,location:d.get('location').trim(),link:d.get('link'),approved:false,open:d.has('open'),created:new Date().toISOString(),members:[{id:u.email,name:u.name,email:u.email}]};if(!b.name)throw Error('Please enter a Band name.');state.user=u;state.bands.push(b);event(u.email,'Your Band is awaiting FAC approval','Staff will review your Band before recruitment begins.');event('staff@example.test','New Band for approval',b.name);save();go('my');}else if(f.id==='meeting-form'){const b=state.bands.find(b=>b.id===hostId);if(b.format==='Online'&&!String(d.get('location')).startsWith('https://'))throw Error('Use a secure https:// meeting link.');b.slot=d.get('slot');b.zone=d.get('zone');b[b.format==='Online'?'link':'location']=d.get('location').trim();b.open=d.has('open');for(const m of b.members)event(m.email,'Your Band meeting details changed','Check your private Band page for updated meeting details.');save();toast('Meeting details saved. Demo updates created.');host();}else if(f.id==='invite-form'){const b=state.bands.find(b=>b.id===hostId),email=d.get('friend').trim().toLowerCase();if(!b.approved)throw Error('Staff approval is needed before invitations.');if(occupied(state,b)>=5)throw Error('This Band has no available places.');if(b.members.some(m=>m.email===email))throw Error('This person is already a member.');if(state.invites.some(i=>i.email===email&&i.band===b.id&&!i.used))throw Error('There’s already an invitation for this person.');const i={id:uid(),band:b.id,email,used:false};state.invites.push(i);event(email,`You're invited to ${b.name}`,'Sign in with this invited email, then open My Band to accept your invitation.');save();toast('Demo invitation created. No email sent.');f.reset();}else if(f.id==='help-form'){state.help.unshift({id:uid(),email:d.get('email'),message:d.get('message'),type:f.dataset.type,resolved:false});save();$('#dialog').close();toast('Demo request saved. View it as FAC staff.');}}catch(err){const error=f.querySelector('#form-error');if(error)error.textContent=err.message;else toast(err.message);}});
document.addEventListener('click',ev=>{const t=ev.target.closest('button');if(!t)return;const ds=t.dataset;if(ds.help)return requestHelp(ds.help);if(t.id==='magic'){const email=ds.email;state.user=state.user?.email===email?state.user:{email,name:'',zone:Intl.DateTimeFormat().resolvedOptions().timeZone};role='participant';save();$('#dialog').close();go(ds.intent);render();return;}
if(ds.role){role=ds.role;if(role==='host'){const pending=state.requests.find(r=>r.status==='review');if(pending)hostId=pending.band;}go(role==='participant'?'my':role);render();return;}
if(ds.host){hostId=ds.host;go('host');render();return;}
if(ds.tab){staffTab=ds.tab;staff();return;}
if(ds.demo==='inbox'){go('inbox');render();return;}
if(ds.demo==='signout'){state.user=null;formProfile=null;role='participant';save();go('home');render();return;}
if(ds.demo==='reset'){openDialog('<h2>Reset this demo?</h2><p>This removes all changes in this browser and restores the sample Bands.</p><button class="danger" id="reset-confirm">Reset demo data</button>');return;}
if(t.id==='reset-confirm'){state=seed();role='participant';hostId='calgary-men';formProfile=null;save();$('#dialog').close();go('home');render();toast('Sample data restored.');return;}
if(t.id==='gps'){
const button=t,form=button.closest('form'),status=form.querySelector('#gps-status');
if(!navigator.geolocation){status.textContent='GPS isn’t available in this browser. Choose a suggested city above, or contact FAC for help.';return;}
button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='Finding your location…';status.textContent='Please allow location access when your browser asks.';
const finish=()=>{button.disabled=false;button.removeAttribute('aria-busy');button.textContent='Use my location';};
navigator.geolocation.getCurrentPosition(p=>{if(!form.isConnected)return;const latitude=Math.round(p.coords.latitude*100)/100,longitude=Math.round(p.coords.longitude*100)/100;form.querySelector('#lat').value=latitude;form.querySelector('#lon').value=longitude;status.textContent='GPS location selected. We’ll use your approximate area for distance matching. Check that the city above describes this area.';finish();},err=>{if(!form.isConnected)return;status.textContent=err.code===1?'Location access wasn’t allowed. You can enable it in your browser settings and try again, or choose a suggested city above.':err.code===3?'Finding your location took too long. Try again or choose a suggested city above.':'We couldn’t find your location. Try again or choose a suggested city above.';finish();},{enableHighAccuracy:false,timeout:12000,maximumAge:60000});return;}
if(ds.accept){if(!accept(state,ds.accept))return toast('No place is available. Refresh and check capacity.');const r=state.requests.find(r=>r.id===ds.accept);event(r.email,'A Band has welcomed you','Your place is reserved. Open My Band to confirm or decline.');save();host();toast('Offer created. Participant confirmation is next.');return;}
if(ds.reject){const r=state.requests.find(r=>r.id===ds.reject);r.status='host-declined';const next=match(state,r.profile);if(next)event(state.bands.find(b=>b.id===next.band).email,'A new Band request',`${r.name} would like to connect.`);save();host();toast('Request declined. Another eligible Band is checked without repeating this one.');return;}
if(ds.confirm){if(!confirm(state,ds.confirm))return toast('This offer is no longer available.');const r=state.requests.find(r=>r.id===ds.confirm),b=state.bands.find(b=>b.id===r.band);event(r.email,'You’re confirmed in your Band','Your private Band page and First Meeting Guide are ready.');event(b.email,'A participant confirmed',`${r.name} has joined your Band.`);if(b.members.length===3)for(const m of b.members)event(m.email,'Your Band is ready to begin','Three people have confirmed. Your Band page has the proposed weekly time and meeting details, the First Meeting Guide and Band Agreement. Agree your first meeting date together.');save();my();return;}
if(ds.decline){const r=state.requests.find(r=>r.id===ds.decline);r.status='declined';tryMatch(state.user);return;}
if(ds.withdraw){const r=state.requests.find(r=>r.id===ds.withdraw);r.status='withdrawn';save();my();toast('Request withdrawn.');return;}
if(t.id==='waitlist'){if(activeRequest())return go('my');state.requests.push({id:uid(),email:state.user.email,name:state.user.name,profile:structuredClone(state.user),status:'waiting',consent:new Date().toISOString()});event(state.user.email,'You’re on the waiting list','We’ll contact you when a suitable Band becomes available. You can withdraw from My Band.');save();go('my');render();return;}
if(t.id==='retry'||ds.rematch){const r=ds.rematch?state.requests.find(r=>r.id===ds.rematch):activeRequest();if(r)r.status='retrying';const result=match(state,r?.profile||state.user);if(!result){if(r)r.status='waiting';save();toast('No eligible Band yet. The waiting-list request is still active.');}else{event(state.bands.find(b=>b.id===result.band).email,'A new Band request',`${result.name} is waiting for your review.`);save();toast('A matching request is ready for host review.');}render();return;}
if(ds.approve){const b=state.bands.find(b=>b.id===ds.approve);b.approved=true;event(b.email,'Your Band is approved','You can invite friends and receive matching requests.');save();staff();return;}
if(ds.return){const b=state.bands.find(b=>b.id===ds.return);event(b.email,'Please review your Band details','FAC requests a review of your meeting details. Your Band remains pending approval.');save();toast('Demo request for changes created.');return;}
if(ds.resolve){state.help.find(h=>h.id===ds.resolve).resolved=true;save();staff();return;}
if(ds.leave){openDialog(`<h2>Leave this Band?</h2><p>You’ll lose access to its private meeting details. We won’t match you back to this Band automatically.</p><button class="danger" data-leave-confirm="${ds.leave}">Leave Band</button>`);return;}
if(ds.leaveConfirm){const b=state.bands.find(b=>b.id===ds.leaveConfirm);b.members=b.members.filter(m=>m.email!==state.user.email);state.requests.push({id:uid(),email:state.user.email,band:b.id,status:'left'});event(b.email,'A member left your Band',`${state.user.name} has left.`);save();$('#dialog').close();my();return;}
if(ds.journey){openDialog(`<h2>What’s next for your Band?</h2><p>Talk together at six months. This preview records a next-step request for FAC; it doesn’t change your membership.</p>${['Renew','Multiply','Reconfigure','Disband','Talk to FAC'].map(v=>`<button class="secondary" data-journey-choice="${v}" data-band="${ds.journey}">${v}</button>`).join(' ')}`);return;}
if(ds.journeyChoice){state.journeys.push({band:ds.band,choice:ds.journeyChoice,date:new Date().toISOString()});state.help.unshift({id:uid(),email:state.user.email,type:'support',message:`Six-month journey request: ${ds.journeyChoice}`,resolved:false});save();$('#dialog').close();toast('Next-step request saved in the demo staff view.');return;}
if(t.id==='print-guide'){window.print();return;}
if(ds.inviteConfirm){if(!$('#invite-agree').checked)return toast('Confirm the Band fits and accept the commitment first.');const i=state.invites.find(i=>i.id===ds.inviteConfirm),b=state.bands.find(b=>b.id===i.band);if(!i||i.used||!b.approved||occupied(state,b)>=5||bandForUser())return toast('This invitation can’t be confirmed. Check membership and available places.');b.members.push({id:i.email,email:i.email,name:state.user.name||i.email.split('@')[0]});i.used=true;const r=activeRequest();if(r)r.status='withdrawn';event(b.email,'Your invitation was accepted',`${i.email} confirmed participation.`);save();$('#dialog').close();my();return;}
});
// An invitation is shown only in the invited person's demo view.
const originalMy=my;my=function(){originalMy();if(!bandForUser()&&state.user){const i=state.invites.find(i=>i.email===state.user.email&&!i.used);if(i){const c=document.createElement('div');c.className='card';c.innerHTML=`<h2>You have a Band invitation.</h2><button class="primary" id="open-invite">Review invitation ↗</button>`;main.querySelector('.page')?.prepend(c);$('#open-invite').onclick=()=>inviteDialog(i);}}};
render();
